#include "KitEditor.h"
KitEditor::KitEditor(PocketProcessor& p):processor(p){
    for(int i=0;i<24;++i){auto& button=pads[size_t(i)];addAndMakeVisible(button);button.setButtonText(juce::String(i+1)+" / "+juce::MidiMessage::getMidiNoteName(60+i,true,true,4));button.onClick=[this,i]{if(auditionNote>=0)processor.keyboard.noteOff(16,auditionNote,0);select(i);auditionNote=-1;if(i<processor.kitPads.load()){auditionNote=60+i;processor.keyboard.noteOn(16,auditionNote,.8f);startTimer(250);}};}
    const char* names[]={"START","END","GAIN","PITCH (st)"};
    for(size_t i=0;i<sliders.size();++i){addAndMakeVisible(sliders[i]);sliders[i].setColour(juce::Slider::textBoxTextColourId,juce::Colour(0xff344d5d));sliders[i].setColour(juce::Slider::textBoxBackgroundColourId,juce::Colour(0xfff4f7fa));sliders[i].setColour(juce::Slider::textBoxOutlineColourId,juce::Colour(0xffbccbd6));sliders[i].setComponentID("pad-control-"+juce::String(int(i)));sliders[i].setSliderStyle(juce::Slider::LinearHorizontal);sliders[i].setTextBoxStyle(juce::Slider::TextBoxRight,false,65,22);sliders[i].onValueChange=[this]{repaint();};addAndMakeVisible(labels[i]);labels[i].setColour(juce::Label::textColourId,juce::Colour(0xff344d5d));labels[i].setText(names[i],juce::dontSendNotification);}
    for(auto* c:{&reverse,&gated,&load,&reset})addAndMakeVisible(*c);
    reverse.setClickingTogglesState(true);gated.setClickingTogglesState(true);gated.setTooltip("Off: one-shot ignores note-off. On: follows the sound ADSR and note-off.");
    load.onClick=[this]{chooseSample();};reset.onClick=[this]{for(const auto* field:{"start","end","gain","pitch","reverse","gated"}){auto* p=processor.state.getParameter(PocketProcessor::padParameterId(selected,field));p->beginChangeGesture();p->setValueNotifyingHost(p->getDefaultValue());p->endChangeGesture();}};
    addAndMakeVisible(title);title.setColour(juce::Label::textColourId,juce::Colour(0xff344d5d));select(0);
}
KitEditor::~KitEditor(){stopTimer();if(auditionNote>=0)processor.keyboard.noteOff(16,auditionNote,0);}
void KitEditor::timerCallback(){stopTimer();if(auditionNote>=0)processor.keyboard.noteOff(16,auditionNote,0);auditionNote=-1;}
void KitEditor::select(int pad){selected=pad;for(auto& a:attachments)a.reset();reverseAttachment.reset();gatedAttachment.reset();const char* fields[]={"start","end","gain","pitch"};for(size_t i=0;i<4;++i)attachments[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(processor.state,PocketProcessor::padParameterId(selected,fields[i]),sliders[i]);reverseAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(processor.state,PocketProcessor::padParameterId(selected,"reverse"),reverse);gatedAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(processor.state,PocketProcessor::padParameterId(selected,"gated"),gated);refresh();}
void KitEditor::refresh(){waveform=processor.kitPadPreview(selected);title.setText("KIT EDITOR / "+juce::String(processor.kitPads.load())+" pads / selected "+juce::String(selected+1)+" / "+processor.kitPadName(selected)+(selected>=processor.kitPads.load()?" (load a sample to expand kit)":""),juce::dontSendNotification);for(int i=0;i<24;++i){pads[size_t(i)].setColour(juce::TextButton::buttonColourId,i==selected?juce::Colour(0xff83c9df):juce::Colour(0xffdbe1e9));pads[size_t(i)].setTooltip(i<processor.kitPads.load()?"Select and audition: "+processor.kitPadName(i):"Empty extension pad; LOAD PAD expands legacy kits to 24");}repaint();}
void KitEditor::resized(){title.setBounds(10,4,getWidth()-20,26);for(int i=0;i<24;++i)pads[size_t(i)].setBounds(10+(i%8)*76,40+(i/8)*65,72,57);const int x=635;for(int i=0;i<4;++i){labels[size_t(i)].setBounds(x,87+i*31,83,26);sliders[size_t(i)].setBounds(x+86,87+i*31,getWidth()-x-100,26);}reverse.setBounds(x,216,110,28);gated.setBounds(x+116,216,100,28);load.setBounds(x+224,216,110,28);reset.setBounds(x+342,216,112,28);}
void KitEditor::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xffe4eaf1));const juce::Rectangle<float> wave(635,37,float(getWidth()-650),42);g.setColour(juce::Colour(0xff283641));g.fillRect(wave);const float start=float(sliders[0].getValue()),end=float(sliders[1].getValue());g.setColour(juce::Colour(0xff315b6c));if(end>start)g.fillRect(wave.withX(wave.getX()+wave.getWidth()*start).withWidth(wave.getWidth()*(end-start)));g.setColour(juce::Colour(0xff80dbed));for(size_t i=0;i<waveform.size();++i){const float x=wave.getX()+float(i)/float(waveform.size())*wave.getWidth(),h=waveform[i]*wave.getHeight()*.48f;g.drawLine(x,wave.getCentreY()-h,x,wave.getCentreY()+h);}if(end<=start){g.setColour(juce::Colours::red);g.drawText("END must exceed START",wave,juce::Justification::centred);}}
void KitEditor::chooseSample(){chooser=std::make_unique<juce::FileChooser>("Load WAV / AIFF into selected pad",juce::File{},"*.wav;*.aif;*.aiff");const int pad=selected;chooser->launchAsync(juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles,[safe=juce::Component::SafePointer<KitEditor>(this),pad](const juce::FileChooser& fc){if(!safe||fc.getResult()==juce::File{})return;juce::String error;if(!safe->processor.loadKitPad(pad,fc.getResult(),error))juce::AlertWindow::showMessageBoxAsync(juce::MessageBoxIconType::WarningIcon,"Pad sample",error);safe->refresh();});}
